46	class CoordinateSystemManager {
47	
48	    private _normalMasterList: CoordinateSystemMaster[] = [];
49	    private _nonSeriesBoxMasterList: CoordinateSystemMaster[] = [];
50	
51	    /**
52	     * Typically,
53	     *  - in `create`, a coord sys lays out based on a given rect;
54	     *  - in `update`, update the pixel and data extent of there axes (if any) based on processed `series.data`.
55	     * After that, a coord sys can serve (typically by `dataToPoint`/`dataToLayout`/`pointToData`).
56	     * If the coordinate system do not lay out based on `series.data`, `update` is not needed.
57	     */
58	    create(ecModel: GlobalModel, api: ExtensionAPI): void {
59	        this._nonSeriesBoxMasterList = dealCreate(nonSeriesBoxCoordSysCreators, true);
60	        this._normalMasterList = dealCreate(normalCoordSysCreators, false);
61	
62	        function dealCreate(creatorMap: CoordinateSystemCreatorMap, canBeNonSeriesBox: boolean) {
63	            let coordinateSystems: CoordinateSystemMaster[] = [];
64	            zrUtil.each(creatorMap, function (creator, type) {
65	                const list = creator.create(ecModel, api);
66	                coordinateSystems = coordinateSystems.concat(list || []);
67	
68	                if (__DEV__) {
69	                    if (canBeNonSeriesBox) {
70	                        // Disallow `update` is a brutal way to ensure `_nonSeriesBoxMasterList`s are ready to
71	                        // serve after `create`. But if `update` has to be involved in `_nonSeriesBoxMasterList`
72	                        // for some future case, more complicated mechanisms need to be introduced.
73	                        zrUtil.each(list, master => zrUtil.assert(!master.update));
74	                    }
75	                }
76	            });
77	            return coordinateSystems;
78	        }
79	    }
