81	    /**
82	     * @see CoordinateSystem['create']
83	     */
84	    update(ecModel: GlobalModel, api: ExtensionAPI): void {
85	        zrUtil.each(this._normalMasterList, function (coordSys) {
86	            coordSys.update && coordSys.update(ecModel, api);
87	        });
88	    }
